-- studio_sound_setup.lua (GENERATED by rr-soundsmith build). Run once in the Studio command bar.
-- Creates SoundService.RR_Mix with the SoundGroup tree. RR_Sound reuses these groups by name and keeps the
-- Volume you set on each group here as its base; player settings and ducking multiply on top at run time.
-- Safe to re-run: existing groups (and their volumes) are kept, never deleted.
local SoundService = game:GetService("SoundService")
local mix = SoundService:FindFirstChild("RR_Mix")
if not mix then mix = Instance.new("Folder"); mix.Name = "RR_Mix"; mix.Parent = SoundService end
local made = {}
do local g = mix:FindFirstChild("Master")
	if not g then g = Instance.new("SoundGroup"); g.Name = "Master"; g.Volume = 1; g.Parent = mix end
	made["Master"] = g end
do local g = made["Master"]:FindFirstChild("SFX")
	if not g then g = Instance.new("SoundGroup"); g.Name = "SFX"; g.Volume = 1; g.Parent = made["Master"] end
	made["SFX"] = g end
do local g = made["SFX"]:FindFirstChild("Alarms")
	if not g then g = Instance.new("SoundGroup"); g.Name = "Alarms"; g.Volume = 1; g.Parent = made["SFX"] end
	made["Alarms"] = g end
do local g = made["SFX"]:FindFirstChild("Actions")
	if not g then g = Instance.new("SoundGroup"); g.Name = "Actions"; g.Volume = 1; g.Parent = made["SFX"] end
	made["Actions"] = g end
do local g = made["SFX"]:FindFirstChild("UI")
	if not g then g = Instance.new("SoundGroup"); g.Name = "UI"; g.Volume = 1; g.Parent = made["SFX"] end
	made["UI"] = g end
do local g = made["Master"]:FindFirstChild("Ambient")
	if not g then g = Instance.new("SoundGroup"); g.Name = "Ambient"; g.Volume = 1; g.Parent = made["Master"] end
	made["Ambient"] = g end
do local g = made["Master"]:FindFirstChild("Music")
	if not g then g = Instance.new("SoundGroup"); g.Name = "Music"; g.Volume = 1; g.Parent = made["Master"] end
	made["Music"] = g end
SoundService.RespectFilteringEnabled = true -- client sounds stay local (tech.audio.local_playback)
SoundService.DistanceFactor = 3.571 -- 1 / tech.units.stud_m; Doppler only
print("RR_Mix ready: " .. #mix:GetDescendants() .. " SoundGroups")
